arguments.command:
cd /workspace && python3 -c "
import json
lines=[json.loads(l) for l in open('results/run100/metrics.jsonl')]
keys_interest=['critic/score/mean','actor/pg_loss','actor/kl_loss','actor/lr','val-core/openai/gsm8k/acc/mean@1','training/global_step']
for l in lines:
    d=l['data']
    s=d.get('training/global_step', l.get('step'))
    row={k: d.get(k) for k in keys_interest if k in d}
    if row:
        # round
        row={k:(round(v,4) if isinstance(v,float) else v) for k,v in row.items()}
        print(s, row)
"

